 44	    private final EntityManagerFactory entityManagerFactory;
 45	
 46	    private final OrderShipmentRepository orderShipmentRepository;
 47	    private final NotificationCommandService notificationService;
 48	    private final OrderShipmentCommandService orderService;
 49	    private final CjTrackingPlaywright cjTrackingPlaywright;
 50	
 51	    private static final int CHUNK_SIZE = 50;
 52	    private static final int SKIP_LIMIT = 50;
 53	
 54	    @Bean
 55	    public Job updateShipmentStatusesJob() {
 56	        log.info("배송 상태 업데이트 작업 구성");
 57	        return new JobBuilder("updateShipmentStatusesJob", jobRepository)
 58	                .start(updateShipmentStatusesStep())
 59	                .build();
 60	    }
 61	
 62	    @Bean
 63	    public Step updateShipmentStatusesStep() {
 64	        log.info("배송 상태 업데이트 스텝 구성: 청크 크기={}, 스킵 제한={}", CHUNK_SIZE, SKIP_LIMIT);
 65	
 66	        return new StepBuilder("updateShipmentStatusesStep", jobRepository)
 67	                .<OrderShipment, OrderShipment>chunk(CHUNK_SIZE, transactionManager)
 68	                .reader(shipmentItemReader())
 69	                .processor(new ShipmentItemProcessor(
 70	                        playwrightBrowserManager(), // Bean or new
 71	                        notificationService,
 72	                        orderService
 73	                ))
 74	                .writer(shipmentJpaItemWriter())
 75	                .faultTolerant()
 76	                .skip(Exception.class)
 77	                .skipLimit(SKIP_LIMIT)
 78	                .listener(shipmentSkipListener())
 79	                // ★ Step Execution Listener로 Browser 관리 리스너 추가
 80	                .listener(new BrowserManageStepListener(playwrightBrowserManager()))
 81	                .build();
 82	    }
 83	
 84	    /**
 85	     * 1) Reader: 상태가 IN_TRANSIT 또는 OUT_FOR_DELIVERY 인 OrderShipment 목록을 페이지 단위로 읽음
 86	     */
 87	    @Bean
 88	    @StepScope
 89	    public JpaPagingItemReader<OrderShipment> shipmentItemReader() {
 90	        log.debug("배송 상태 업데이트 ItemReader 구성");
 91	        return new JpaPagingItemReaderBuilder<OrderShipment>()
 92	                .name("shipmentItemReader")
 93	                .entityManagerFactory(entityManagerFactory)
 94	                .pageSize(CHUNK_SIZE)
 95	                .queryString("SELECT s FROM OrderShipment s WHERE s.status IN ('IN_TRANSIT','OUT_FOR_DELIVERY') AND s.trackingNumber IS NOT NULL")
 96	                .build();
 97	    }
 98	
 99	    /**
100	     * 2) Processor: 각 OrderShipment에 대해 CJ대한통운 페이지를 조회하여 상태 갱신
101	     *    - parseCjLogisticsStatus(...) 를 통해 배송 상태 파싱
102	     *    - DELIVERY 완료 시 알림, Order 상태 완료 등도 여기서 처리 가능
103	     */
104	    @Bean
105	    @StepScope
106	    public ItemProcessor<OrderShipment, OrderShipment> shipmentItemProcessor() {
107	        log.debug("배송 상태 업데이트 ItemProcessor 구성");
108	
109	        // 만약 Processor를 여러 단계로 나누고 싶다면 CompositeItemProcessorBuilder 사용도 가능
110	        return orderShipment -> {
111	            String trackingNumber = orderShipment.getTrackingNumber();
112	            Long shipmentId = orderShipment.getId();
113	
114	            if (trackingNumber == null || trackingNumber.isBlank()) {
115	                log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
116	                throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
117	            }
118	
119	            log.info("배송 상태 조회 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
120	                    shipmentId, trackingNumber, orderShipment.getStatus());
121	
122	            try {
123	                // 2-1) 현재 상태 가져오기
124	                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
125	                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}", shipmentId, currentStatus);
126	
127	                // 2-2) 매핑
128	                ShipmentStatus newStatus = mapToShipmentStatus(currentStatus);
129	                log.debug("배송 상태 매핑 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);
130	
131	                // 현재 상태와 동일한 경우 중복 처리 방지
132	                if (orderShipment.getStatus() == newStatus) {
133	                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
134	                            shipmentId, newStatus);
135	                    return orderShipment;
136	                }
137	
138	                // 2-3) 상태에 따른 처리
139	                if (newStatus == ShipmentStatus.DELIVERED) {
140	                    log.info("배송 완료 처리: shipmentId={}, orderId={}",
141	                            shipmentId, orderShipment.getOrder().getId());
142	
143	                    orderShipment.updateStatus(ShipmentStatus.DELIVERED);
144	                    // Order 상태도 COMPLETED 로 변경
145	                    orderService.completeOrder(orderShipment.getOrder().getId());
146	                    // 알림 발송
147	                    notificationService.notifyShipmentCompleted(orderShipment.getOrder());
148	                }
149	                else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
150	                    log.info("배송 출발 처리: shipmentId={}", shipmentId);
151	                    orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
152	                    // 필요시 알림, 로직 추가
153	                }
154	                else {
155	                    log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
156	                    orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
157	                }
158	
159	                log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}", shipmentId, orderShipment.getStatus());
160	                return orderShipment; // Writer로 넘김
161	
162	            } catch (Exception e) {
163	                log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
164	                        shipmentId, trackingNumber, e.getMessage(), e);
165	
166	                // ShipmentException 타입이 아닌 경우 래핑
167	                if (!(e instanceof ShipmentException)) {
168	                    throw new ShipmentException(
169	                            ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
170	                            "배송 상태 조회 중 오류 발생: " + e.getMessage(),
171	                            e
172	                    );
173	                }
174	                throw e;
175	            }
176	        };
177	    }
178	
179	    /**
180	     * CJ대한통운 배송 상태 조회를 위한 메서드
181	     *
182	     * @param trackingNumber 운송장 번호
183	     * @return 배송 상태 텍스트
184	     * @throws Exception 조회 실패 시 발생
185	     */
186	    private String parseCjLogisticsStatus(String trackingNumber) throws Exception {
187	        log.debug("운송장 조회 시작 (Jsoup): trackingNumber={}", trackingNumber);
188	
189	        try {
190	            // 예시: 로직 단순화
191	            String url = "https://trace.cjlogistics.com/next/tracking.html?wblNo=" + trackingNumber;
192	            Document doc = Jsoup.connect(url).get();
193	            // tbody#statusDetail 의 마지막 tr => 5번째 td
194	            Elements rows = doc.select("tbody#statusDetail tr");
195	            if (rows.isEmpty()) {
196	                log.warn("배송 정보가 없음: trackingNumber={}", trackingNumber);
197	                throw new ShipmentException(
198	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
199	                        "배송 정보가 없습니다. trackingNo=" + trackingNumber
200	                );
201	            }
202	
203	            String status = rows.last().select("td").get(4).text();
204	            log.debug("운송장 조회 완료: trackingNumber={}, status={}", trackingNumber, status);
205	            return status;
206	
207	        } catch (Exception e) {
208	            log.error("운송장 조회 실패: trackingNumber={}, error={}", trackingNumber, e.getMessage(), e);
209	
210	            if (e instanceof ShipmentException) {
211	                throw e;
212	            }
213	
214	            throw new ShipmentException(
215	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
216	                    "배송 정보 조회 중 오류 발생: " + e.getMessage(),
217	                    e
218	            );
219	        }
220	    }
221	
222	    /**
223	     * 배송사 상태 텍스트를 내부 ShipmentStatus로 매핑합니다.
224	     *
225	     * @param statusText 배송사 상태 텍스트
226	     * @return 매핑된 ShipmentStatus
227	     */
228	    private ShipmentStatus mapToShipmentStatus(String statusText) {
229	        return switch (statusText) {
230	            case "배송완료" -> ShipmentStatus.DELIVERED;
231	            case "배송출발" -> ShipmentStatus.OUT_FOR_DELIVERY;
232	            default -> ShipmentStatus.IN_TRANSIT;
233	        };
234	    }
235	
236	    /**
237	     * 3) Writer: DB에 반영 (상태 갱신)
238	     */
239	    @Bean
240	    @StepScope
241	    public JpaItemWriter<OrderShipment> shipmentJpaItemWriter() {
242	        log.debug("배송 상태 업데이트 ItemWriter 구성");
243	        JpaItemWriter<OrderShipment> writer = new JpaItemWriter<>();
244	        writer.setEntityManagerFactory(entityManagerFactory);
245	        return writer;
246	    }
247	
248	    /**
249	     * SkipListener: 예외 발생 시 로그
250	     */
251	    @Bean
252	    public SkipListener<OrderShipment, OrderShipment> shipmentSkipListener() {
253	        return new SkipListener<>() {
254	            @Override
255	            public void onSkipInProcess(OrderShipment item, Throwable t) {
256	                if (item != null) {
257	                    log.error("[Skip] 배송 상태 처리 스킵: shipmentId={}, trackingNumber={}, status={}, 사유={}",
258	                            item.getId(),
259	                            item.getTrackingNumber(),
260	                            item.getStatus(),
261	                            t.getMessage(),
262	                            t);
263	                } else {
264	                    log.error("[Skip] 배송 상태 처리 스킵: item=null, 사유={}", t.getMessage(), t);
265	                }
266	            }
267	
268	            @Override
269	            public void onSkipInRead(Throwable t) {
270	                log.error("[SkipRead] 배송 정보 읽기 스킵: 사유={}", t.getMessage(), t);
271	            }
272	
273	            @Override
274	            public void onSkipInWrite(OrderShipment item, Throwable t) {
275	                if (item != null) {
276	                    log.error("[SkipWrite] 배송 상태 저장 스킵: shipmentId={}, trackingNumber={}, status={}, 사유={}",
277	                            item.getId(),
278	                            item.getTrackingNumber(),
279	                            item.getStatus(),
280	                            t.getMessage(),
281	                            t);
282	                } else {
283	                    log.error("[SkipWrite] 배송 상태 저장 스킵: item=null, 사유={}", t.getMessage(), t);
284	                }
285	            }
286	        };
287	    }
288	
289	    /**
290	     * PlaywrightBrowserManager 빈 정의
291	     */
292	    @Bean
293	    public PlaywrightBrowserManager playwrightBrowserManager() {
294	        log.debug("Playwright 브라우저 매니저 빈 생성");
295	        return new PlaywrightBrowserManager();
296	    }
